using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;
/// <summary>Driving touch UI: steering slider zone, accelerator and brake.</summary>
public class StreetLegendDrivingHUD:MonoBehaviour{
 public StreetLegendVehicleController vehicle; Canvas canvas; bool gas,brake; float steer; int steeringFinger=-1; Vector2 steeringStart;
 void Start(){if(!vehicle)vehicle=FindObjectOfType<StreetLegendVehicleController>();Build(); }
 void Update(){if(!vehicle)return;for(int i=0;i<Input.touchCount;i++){Touch t=Input.GetTouch(i);if(t.phase==TouchPhase.Began&&t.position.x<Screen.width*.5f){steeringFinger=t.fingerId;steeringStart=t.position;}if(t.fingerId==steeringFinger){if(t.phase==TouchPhase.Moved||t.phase==TouchPhase.Stationary)steer=Mathf.Clamp((t.position.x-steeringStart.x)/(Screen.width*.22f),-1,1);if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled){steeringFinger=-1;steer=0;}}}vehicle.SetInput(steer,gas?1:0,brake);}
 void Build(){var go=new GameObject("Driving HUD",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=25;go.GetComponent<CanvasScaler>().uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;go.GetComponent<CanvasScaler>().referenceResolution=new Vector2(1920,1080);if(!FindObjectOfType<EventSystem>())new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));ButtonControl(go.transform,"ACCEL",new Vector2(.88f,.2f),()=>gas=true,()=>gas=false);ButtonControl(go.transform,"BRAKE",new Vector2(.72f,.2f),()=>brake=true,()=>brake=false);}
 void ButtonControl(Transform p,string label,Vector2 a,UnityEngine.Events.UnityAction down,UnityEngine.Events.UnityAction up){var g=new GameObject(label,typeof(RectTransform),typeof(Image),typeof(Button));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=a;r.sizeDelta=new Vector2(180,150);g.GetComponent<Image>().color=new Color(.08f,.2f,.32f,.8f);var b=g.GetComponent<Button>();b.onClick.AddListener(down);var txt=new GameObject("Label",typeof(RectTransform),typeof(Text));txt.transform.SetParent(g.transform,false);var tr=txt.GetComponent<RectTransform>();tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=tr.offsetMax=Vector2.zero;var t=txt.GetComponent<Text>();t.text=label;t.font=Resources.GetBuiltinResource<Font>("Arial.ttf");t.fontSize=28;t.alignment=TextAnchor.MiddleCenter;t.color=Color.white;t.raycastTarget=false;}
 void OnDisable(){if(vehicle)vehicle.SetInput(0,0,true);}
}
